INSERT INTO DO_DETAIL ( DOD_NO, DO_NO, PRODUCT_CODE, ORDER_QTY, UNIT_PRICE, SUP_AMT, VAT_AMT, DC_AMT, COMPANY_CODE ) SELECT fn_generate_code('DOD', ''), #{doNo}, t.productCode, t.orderQty, t.unitPrice, t.supAmt, t.vatAmt, t.dcAmt, #{companyCode} FROM (
SELECT #{d.productCode} AS productCode, #{d.orderQty} AS orderQty, #{d.unitPrice} AS unitPrice, #{d.supAmt} AS supAmt, #{d.vatAmt} AS vatAmt, #{d.dcAmt} AS dcAmt FROM DUAL
) t

mapper.select:
SELECT CUS_CODE, CUS_NAME, CEO_NAME, TEL, ADDR, ACTIVE_STATUS, GBN
FROM CUSTOMER
WHERE COMPANY_CODE = #{companyCode}

mapper.update:
UPDATE CUSTOMER
CEO_NAME = #{ceoName}, EMP_NAME = #{empName}, CUS_NAME = #{cusName}, BIZ_NO = #{bizNo}, BIZ_TYPE = #{bizType}, BIZ_CATEGORY = #{bizCategory}, TEL = #{tel}, EMAIL = #{email}, ADDR = #{addr}, ZIP_CODE = #{zipCode}, ACTIVE_STATUS = #{activeStatus}, GBN = #{gbn}, BANK_NAME = #{bankName}, BANK_ACCOUNT = #{bankAccount},
WHERE CUS_CODE = #{cusCode}

UPDATE CREDIT_MASTER
CREDIT_LIMIT = #{creditLimit}, CREDIT_GRADE = #{creditGrade}, START_DATE = #{startDate}, EXPIRE_DATE = #{expireDate}, ACTIVE_STATUS = #{cActiveStatus},
WHERE CUS_CODE = #{cusCode}

